// 只反轉後半段數字，與前半段比較（不轉字串、不會溢位）
// 時間複雜度: O(log n)，空間複雜度: O(1)
function isPalindrome(x) {
    if (x < 0 || (x % 10 === 0 && x !== 0))
        return false;
    let half = 0;
    while (x > half) {
        half = half * 10 + (x % 10);
        x = Math.floor(x / 10);
    }
    return x === half || x === Math.floor(half / 10); // 奇數位數時去掉中間位
}

